using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Threading;using System.Web.Script.Serialization;using UsbRecovery;
public static class TelegramMediaPortableTests
{
    static int checks;static string fixtures,work;static JavaScriptSerializer json=new JavaScriptSerializer();
    static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
    static string Hash(string p){using(var file=File.OpenRead(p))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(file)).Replace("-","").ToLowerInvariant();}
    static ArchiveSearchResult Search(string output,string query,string kind){var result=ArchiveSearchService.Search(output,"Telegram",query,kind,0,CancellationToken.None);Check(result.status=="complete"||result.status=="partial","actual frozen archive search");return result;}
    static string Analyze(string name){string output=Path.Combine(work,name);var result=TelegramAnalysisService.AnalyzeSelected(output,Path.Combine(fixtures,name),"",false,CancellationToken.None,null);Check(result.Status!="error","media worker analysis completes");Check(!Directory.Exists(output+".work")&&!File.Exists(Path.Combine(output,"job.incomplete")),"media complete output and cleanup");return output;}
    static List<Dictionary<string,object>> Rows(object value){return ((IEnumerable)value).Cast<object>().Cast<Dictionary<string,object>>().ToList();}
    static void Origins(string output,bool historical)
    {
        var record=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(output,"attachment-metadata.json")));var attachments=Rows(record["attachments"]);Check(attachments.Count==1,"cached bytes content deduplicated");var origins=Rows(attachments[0]["sources"]);Check(origins.All(o=>Convert.ToString(o["offset_kind"])=="sqlite_tl_blob_relative"&&o.ContainsKey("blob_offset")&&!o.ContainsKey("offset")),"BLOB positions never called physical DB offsets");Check(origins.All(o=>o.ContainsKey("source_sha256")&&Convert.ToString(o["source_record"]).Contains("photo.sizes[")),"thumbnail linked to typed record and source hash");if(historical)Check(origins.Any(o=>o.ContainsKey("wal_snapshot_sha256")&&o.ContainsKey("wal_sha256")),"historical thumbnail carries committed snapshot provenance");
    }
    public static int Main(string[] args)
    {
        fixtures=Path.GetFullPath(args[0]);work=Path.Combine(Path.GetTempPath(),"TelegramMediaPortable-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);
        try{
            var manifest=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(fixtures,"manifest.json")));Check(Convert.ToBoolean(manifest["synthetic"]),"synthetic media manifest");var files=Rows(manifest["files"]);foreach(var f in files)Check(Hash(RecoveryCatalog.SafeFile(fixtures,Convert.ToString(f["path"])))==Convert.ToString(f["sha256"]),"input hash matches independent generator");string expected=Convert.ToString(manifest["thumbnail_sha256"]);
            string output=Analyze("input");var all=Search(output,"","backup");Check(all.total==5,"supported photo records survive while live-photo unsupported");var caption=Search(output,"Photo caption recipe","backup").records.Single(x=>x.text=="Photo caption recipe");Check(caption.media_kind=="photo"&&caption.media_status=="photo_reference_only"&&caption.attachments.Length==0,"caption retained without fabricated full photo");
            var thumb=Search(output,"Cached thumbnail recipe","backup").records.Single();Check(thumb.thumbnail_count!=null&&Convert.ToInt32(thumb.thumbnail_count)==1&&thumb.attachments.Length==1,"valid cached thumbnail linked to message");string target=ArchiveSearchService.VerifiedAttachment(output,thumb.attachments[0]);Check(Hash(target)==expected&&new FileInfo(target).Length==645,"exact cached thumbnail bytes through packaged verified attachment API");Check(all.records.Any(x=>x.text==""&&x.media_kind=="photo"),"photo with no caption retained without invented text");Check(all.records.Any(x=>x.text=="Legacy photo caption recipe"),"legacy caption retained");Check(Search(output,"Damaged thumbnail caption","backup").records.Single().attachments.Length==0,"damaged thumbnail not published as usable attachment");Origins(output,false);
            string history=Analyze("history");var current=Search(history,"Current photo caption","backup");var older=Search(history,"Prior photo caption","previous");Check(current.total==1&&older.total==1,"current and earlier photo captions separate");Check(older.records[0].wal_proof=="all_pages_from_validated_wal"&&older.records[0].attachments.Length==1,"prior photo record needs full WAL snapshot proof");Check(Hash(ArchiveSearchService.VerifiedAttachment(history,older.records[0].attachments[0]))==expected,"prior thumbnail exact");Origins(history,true);
            File.AppendAllText(target,"modified");bool rejected=false;try{ArchiveSearchService.VerifiedAttachment(output,thumb.attachments[0]);}catch(IOException){rejected=true;}Check(rejected,"modified thumbnail cannot reuse stored hash success");foreach(var f in files)Check(Hash(RecoveryCatalog.SafeFile(fixtures,Convert.ToString(f["path"])))==Convert.ToString(f["sha256"]),"original DB/WAL/images unchanged");Console.WriteLine("PASS TelegramMediaPortable: "+checks+" checks; photo captions, exact inline thumbnails, missing/damaged/unsupported media, committed WAL provenance, hashverified attachment through frozen helper; synthetic only.");return 0;
        }catch(Exception e){Console.Error.WriteLine(e);return 1;}
        finally{if(Path.GetFullPath(work).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase))try{Directory.Delete(work,true);}catch{}}
    }
}
